        for (int dy = -S; dy <= S; dy++)
            for (int dx = -S; dx <= S; dx++) {
                double sw1 = 0, sw2 = 0, sd = 0;
                for (int j = 0; j < MAP_PS; j++) {
                    const uint8_t *wrow = I + (cv + dy - r + j) * w + cu + dx - r, *trow = m->t + j * MAP_PS;
                    for (int i = 0; i < MAP_PS; i++) { double q = wrow[i]; sw1 += q; sw2 += q * q; sd += (trow[i] - tm) * q; }
                }
                double var = sw2 - sw1 * sw1 / (MAP_PS * MAP_PS);
                double z = var > 1e-6 ? sd / (tn * sqrt(var)) : -1;
                cc[(dy + S) * sw + dx + S] = z;
                if (z > best) { best = z; bx = dx; by = dy; }
            }
        for (int dy = -S; dy <= S; dy++)
            for (int dx = -S; dx <= S; dx++)
                if ((abs(dx - bx) > 2 || abs(dy - by) > 2) && cc[(dy + S) * sw + dx + S] > second) second = cc[(dy + S) * sw + dx + S];
        if (best < MAP_ZNCC || best - second < 0.04) continue;
        mp_match++;
